package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"     // PIC X len=1 = "N"
var WsFirstFlag string = "Y"   // PIC X len=1 = "Y"
var WsPrevBranch string = "  " // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    " // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.NewFromInt(0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0                                  // PIC 99 len=2 = 0
var WsAmtEd string                                       // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                                       // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                                       // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var curRec LedgerRec
var inputFile *os.File
var inputScanner *bufio.Scanner

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func formatUnsigned(val decimal.Decimal, picture string) string {
	parts := strings.Split(picture, ".")
	leftPic := parts[0]
	rightPic := ""
	if len(parts) > 1 {
		rightPic = parts[1]
	}
	intSlots := 0
	for _, c := range leftPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range rightPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}
	absVal := val.Abs()
	totalCentsDec := absVal.Shift(int32(fracSlots)).Truncate(0)
	totalCents := totalCentsDec.IntPart()
	powFrac := pow10(fracSlots)
	intPart := int64(0)
	fracPart := int64(0)
	if fracSlots > 0 {
		intPart = totalCents / powFrac
		fracPart = totalCents % powFrac
	} else {
		intPart = totalCents
	}
	modInt := pow10(intSlots)
	if modInt != 0 {
		intPart = intPart % modInt
	}
	intStr := fmt.Sprintf("%0*d", intSlots, intPart)
	fracStr := ""
	if fracSlots > 0 {
		fracStr = fmt.Sprintf("%0*d", fracSlots, fracPart)
	}
	// build left
	leftOut := make([]rune, len(leftPic))
	dIdx := 0
	for i, ch := range leftPic {
		if ch == ',' {
			leftOut[i] = ','
		} else {
			leftOut[i] = rune(intStr[dIdx])
			dIdx++
		}
	}
	suppressed := true
	for i, ch := range leftPic {
		if leftOut[i] == ',' {
			if suppressed {
				leftOut[i] = ' '
			}
		} else {
			isZ := ch == 'Z'
			if suppressed {
				if isZ && leftOut[i] == '0' {
					leftOut[i] = ' '
				} else {
					suppressed = false
				}
			}
		}
	}
	rightOut := make([]rune, len(rightPic))
	for i := range rightPic {
		if i < len(fracStr) {
			rightOut[i] = rune(fracStr[i])
		} else {
			rightOut[i] = '0'
		}
	}
	if len(rightPic) > 0 {
		return string(leftOut) + "." + string(rightOut)
	}
	return string(leftOut)
}

func formatSigned(val decimal.Decimal, picture string) string {
	signChar := ' '
	if val.IsNegative() {
		signChar = '-'
	}
	magPic := picture
	if len(picture) > 0 && picture[0] == '-' {
		magPic = picture[1:]
	}
	part := formatUnsigned(val.Abs(), magPic)
	return string(signChar) + part
}

func formatAmtEd(val decimal.Decimal) string {
	return formatUnsigned(val, "ZZ,ZZ9.99")
}
func formatBalEd(val decimal.Decimal) string {
	return formatSigned(val, "-Z,ZZZ,ZZ9.99")
}
func formatTotEd(val decimal.Decimal) string {
	return formatSigned(val, "-ZZZ,ZZZ,ZZ9.99")
}

func truncateToPic(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	trunc := val.Truncate(int32(scale))
	mod := pow10(intDigits + scale)
	cents := trunc.Shift(int32(scale)).Truncate(0).IntPart()
	sign := int64(1)
	if cents < 0 {
		sign = -1
		cents = -cents
	}
	cents = cents % mod
	cents *= sign
	return decimal.New(cents, int32(-scale))
}
func truncateBal(v decimal.Decimal) decimal.Decimal       { return truncateToPic(v, 7, 2) }
func truncateBranchTot(v decimal.Decimal) decimal.Decimal { return truncateToPic(v, 9, 2) }
func truncateGrandTot(v decimal.Decimal) decimal.Decimal  { return truncateToPic(v, 9, 2) }
func truncateSkipped(v int64) int64 {
	mod := int64(100)
	v = v % mod
	if v < 0 {
		v += mod
	}
	return v
}

// paragraphs

func MainPara() {
	OpenLedgerFile()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	CloseLedgerFile()
	GrandPara()
}

func OpenLedgerFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		return
	}
	inputFile = f
	inputScanner = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	inputScanner.Buffer(buf, 10*1024*1024)
}

func CloseLedgerFile() {
	if inputFile != nil {
		inputFile.Close()
	}
}

func ReadPara() {
	if inputScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !inputScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := inputScanner.Text()
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	curRec.BrBranch = line[0:2]
	curRec.BrAcct = line[2:6]
	curRec.BrType = line[6:7]
	amtField := line[7:14]
	var n int64 = 0
	for i := 0; i < len(amtField); i++ {
		c := amtField[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n*10 + 0
		}
	}
	curRec.BrAmt = decimal.New(n, -2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		newBal := WsBal.Add(curRec.BrAmt)
		WsBal = truncateBal(newBal)
		fmt.Printf("%s D %s\n", curRec.BrAcct, WsAmtEd)
	case "C":
		newBal := WsBal.Sub(curRec.BrAmt)
		WsBal = truncateBal(newBal)
		fmt.Printf("%s C %s\n", curRec.BrAcct, WsAmtEd)
	default:
		WsSkipped = truncateSkipped(WsSkipped + 1)
		fmt.Printf("%s ? SKIPPED\n", curRec.BrAcct)
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	newBranch := WsBranchTot.Add(WsBal)
	WsBranchTot = truncateBranchTot(newBranch)
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	newGrand := WsGrandTot.Add(WsBranchTot)
	WsGrandTot = truncateGrandTot(newGrand)
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	fmt.Printf("SKIPPED: %s\n", skippedStr)
}

func main() {
	MainPara()
}
